function workContextBoundToolName(value: unknown): string | undefined {
  if (typeof value !== "string") return undefined;
  for (const name of WORK_CONTEXT_BOUND_TOOLS) {
    if (value === name || value.endsWith(`__${name}`)) return name;
  }
  return undefined;
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

const DIRECT_CODEX_CONTEXT_HOOK_PATTERN =
  /(?:^|[\s|;&])(?:(?:node|tsx)\s+)?["']?(?:[^\s"'|;&]+\/)*anvil(?:\.ts)?["']?\s+codex\s+(?:context-hook|session-start-hook)(?=$|[\s|;&])/m;

function isDirectCodexContextHookProbe(toolName: unknown, toolInput: unknown): boolean {
  if (toolName !== "Bash" || !isRecord(toolInput)) return false;
  const command = toolInput.command;
  return typeof command === "string" && DIRECT_CODEX_CONTEXT_HOOK_PATTERN.test(command);
}

function stripCallerMutationAuthority(
  input: Record<string, unknown>,
  _toolName: string,
): Record<string, unknown> {
  return Object.fromEntries(
    Object.entries(input).filter(([key]) => !HOST_OWNED_ROUTING_FIELDS.has(key)),
  );
}

function optionalHookIdentifier(value: unknown): string | undefined {
  return typeof value === "string" && value.trim().length > 0 ? value.trim() : undefined;
