async function brainUsage(args: string[]): Promise<void> {
  const flags = parseFlags(args);
  const result = await readBrainUsage({
    cwd: flags.cwd,
    stateRoot: flags["state-root"],
    limit: parseLimit(flags.limit),
  });

  if (flags.json) {
    process.stdout.write(`${JSON.stringify(result, null, 2)}\n`);
    return;
  }

  if (result.kind === "missing") {
    process.stdout.write(`No brain usage journal found at ${result.path}\n`);
    return;
  }
  if (result.kind === "malformed") {
    process.stdout.write(`Malformed brain usage journal at ${result.path}: ${result.message}\n`);
    return;
  }
  for (const item of result.items) {
    const brain = item.brain_alias
      ? ` ${item.brain_alias}${item.brain_id ? ` [${item.brain_id}]` : ""}`
      : item.brain
        ? ` ${item.brain} [legacy]`
        : item.brain_identity_status === "unresolved"
          ? ` unresolved [${item.brain_identity_error ?? "unknown"}]`
          : "";
    const pages = item.pages && item.pages.length > 0 ? ` [${item.pages.join(", ")}]` : "";
    const outcome = item.outcome ? ` - ${item.outcome}` : "";
    process.stdout.write(`${item.created_at}${brain} ${item.event} ${item.severity}: ${item.trigger}${pages}${outcome}\n`);
  }
}

function formatCountList<T extends string>(events: readonly T[], counts: Record<T, number>): string {
  return events.map((event) => `${event}=${counts[event]}`).join(", ");
}

function formatRate(value: number | null): string {
  return value === null ? "n/a" : `${(value * 100).toFixed(1)}%`;
}

function scriptSafeJson(value: unknown): string {
  return JSON.stringify(value).replace(/[<>&\u2028\u2029]/g, (character) => {
    switch (character) {
      case "<":
        return "\\u003c";
      case ">":
        return "\\u003e";
      case "&":
        return "\\u0026";
      case "\u2028":
        return "\\u2028";
      case "\u2029":
        return "\\u2029";
      default:
        return character;
    }
  });
}

function parsePort(value: string | undefined): number {
  if (value === undefined) return DEFAULT_BRAIN_DASHBOARD_PORT;
  const parsed = Number(value);
  if (!Number.isInteger(parsed) || parsed < 0 || parsed > 65535) fail("--port must be an integer from 0 to 65535");
  return parsed;
}

function parseRefreshMs(value: string | undefined): number {
  if (value === undefined) return 2000;
  const parsed = Number(value);
  if (!Number.isInteger(parsed) || parsed < 250 || parsed > 60000) {
    fail("--refresh-ms must be an integer from 250 to 60000");
  }
  return parsed;
}

function normalizeHost(value: string | undefined): string {
  const host = value ?? "127.0.0.1";
  if (host.trim().length === 0 || /\s/.test(host)) fail("--host must be a non-empty host without whitespace");
  return host;
}

function injectDashboardConfig(template: string, config: { refreshMs: number }): string {
  const marker = "    <script type=\"module\">";
  if (!template.includes(marker)) throw new Error("Brain usage dashboard template is missing module script marker");
  const injection = [
    "    <script>",
    `      globalThis.__ANVIL_BRAIN_USAGE_DASHBOARD__ = ${scriptSafeJson(config)}`,
    "    </script>",
    marker,
  ].join("\n");
  return template.replace(marker, injection);
}

function sendResponse(
  response: ServerResponse,
