function lensMcpLaunch(): { command: string; args: string[] } {
  const lensRoot = process.env.ANVIL_LENS_ROOT ?? process.env.LENS_ROOT ?? resolve(homedir(), "lens");
  return {
    command: process.env.ANVIL_LENS_MCP_COMMAND ?? resolve(lensRoot, "node_modules/.bin/tsx"),
    args: [process.env.ANVIL_LENS_MCP_SCRIPT ?? resolve(lensRoot, "src/mcp/server.ts")],
  };
}

function mcpTextContent(value: unknown): string {
  const content = (value as { content?: Array<{ type?: string; text?: string }> }).content;
  const text = content?.find((item) => item.type === "text" && typeof item.text === "string")?.text;
  if (text === undefined) throw new Error("Lens MCP response did not include text content");
  retu

rn text;
}

function renderLensError(value: unknown): string {
  if (typeof value === "object" && value !== null) {
    const validation = (value as { validation?: { errors?: unknown } }).validation;
    const refused = (value as { refused?: { reason?: unknown } }).refused;
    if (typeof refused?.reason === "string") return refused.reason;
    if (Array.isArray(validation?.errors) && validation.errors.length > 0) return validation.errors.join("; ");
  }
  return JSON.stringify(value);
}

function isPathInside(root: string, candidate: string): boolean {
  const path = relative(root, candidate);
  return path === "" || (!path.startsWith(`..${sep}`) && path !== ".." && !isAbsolute(path));
}

async function renderLensGraphHtml(
  metrics: Awaited<ReturnType<typeof summarizeBrainUsage>> & { kind: "ok" },
  workspaceOptions: WorkspaceOptions,
): Promise<string> {
  const graph = buildBrainUsageLensGraph(metrics);
  const outDir = join(resolveBrainUsageWorkspace(workspaceOptions).brainUsageRoot, "lens");
  const { command, args } = lensMcpLaunch();
  const transport = new StdioClientTransport({ command, args });
  const client = new Client({ name: "anvil-brain-dashboard", version: "0.0.0" });
  await client.connect(transport);
  try {
    const response = await client.callTool({
      name: "lens_render",
      arguments: { id: "node-graph", data: graph, out_dir: outDir },
    });
    const result = JSON.parse(mcpTextContent(response)) as { ok?: boolean; path?: unknown };
    if (result.ok !== true || typeof result.path !== "string") {
      throw new Error(`Lens render failed: ${renderLensError(result)}`);
    }
    const [resolvedOutDir, resolvedOutput] = await Promise.all([realpath(outDir), realpath(result.path)]);
    if (!isPathInside(resolvedOutDir, resolvedOutput)) {
      throw new Error("Lens render path escaped the dashboard output directory");
    }
    return await readFile(resolvedOutput, "utf8");
  } finally {
    await client.close();
  }
}

async function brainMetrics(args: string[]): Promise<void> {
  const flags = parseFlags(args);
  const result = await summarizeBrainUsage({
    cwd: flags.cwd,
    stateRoot: flags["state-root"],
  });

  if (flags.json) {
    process.stdout.write(`${JSON.stringify(result, null, 2)}\n`);
    return;
  }

  if (result.kind === "missing") {
    process.stdout.write(`No brain usage journal found at ${result.path}\n`);
    return;
  }
  if (result.kind === "malformed") {
    process.stdout.write(`Malformed brain usage journal at ${result.path}: ${result.message}\n`);
    return;
  }

  const brainCounts = Object.entries(result.by_brain)
    .sort((left, right) => right[1] - left[1] || left[0].localeCompare(right[0]))
    .map(([brainId, count]) => `${result.brain_aliases[brainId] ?? "unknown"} [${brainId}]=${count}`)
    .join(", ");
  const bucketCounts = Object.entries(result.by_trigger_bucket)
    .sort((left, right) => right[1] - left[1] || left[0].localeCompare(right[0]))
    .map(([bucket, count]) => `${bucket}=${count}`)
    .join(", ");
  process.stdout.write(
    [
      `Brain usage metrics for ${result.path}`,
      `Total events: ${result.total}`,
      `Recall events: ${result.recall.total} (${formatCountList(BRAIN_USAGE_RECALL_EVENTS, result.recall.by_event)})`,
      `Recall success: ${formatRate(result.recall.success.rate)} (${result.recall.success.numerator}/${result.recall.success.denominator})`,
      `Recall degradation: ${formatRate(result.recall.degradation.rate)} (${result.recall.degradation.numerator}/${result.recall.degradation.denominator})`,
      `Recall instrumentation: ${result.recall.instrumentation.instrumented_records}/${result.recall.instrumentation.eligible_records} (${formatRate(result.recall.instrumentation.coverage)})`,
      `Coverage events: ${result.coverage.total} (${formatCountList(BRAIN_USAGE_COVERAGE_EVENTS, result.coverage.by_event)})`,
      `Incident events: ${result.incidents.total} (${formatCountList(BRAIN_USAGE_INCIDENT_EVENTS, result.incidents.by_event)})`,
      `Severity: ${formatCountList(BRAIN_USAGE_SEVERITIES, result.by_severity)}`,
      `Brains: ${brainCounts || "none"}`,
      `Identity quality: resolved=${result.brain_identity.resolved_events}, legacy_normalized=${result.brain_identity.legacy_normalized_events}, unresolved=${result.brain_identity.unresolved_events}, unassigned=${result.brain_identity.unassigned_events}`,
      `Trigger buckets: ${bucketCounts || "none"}`,
      ...(result.first_created_at !== undefined ? [`First event: ${result.first_created_at}`] : []),
      ...(result.last_created_at !== undefined ? [`Last event: ${result.last_created_at}`] : []),
    ].join("\n") + "\n",
  );
}

async function brainDashboard(args: string[]): Promise<void> {
  const flags = parseFlags(args);
  const host = normalizeHost(flags.host);
  const port = parsePort(flags.port);
  const refreshMs = parseRefreshMs(flags["refresh-ms"]);
  const workspaceOptions = { cwd: flags.cwd, stateRoot: flags["state-root"] };
  const templatePath = resolve(dirname(currentFile), "../docs/brain-usage-dashboard.html");

  const server = createServer((request, response) => {
    const requestUrl = new URL(request.url ?? "/", `http://${host}`);
    if (request.method !== "GET" && request.method !== "HEAD") {
      sendJson(response, 405, { error: { code: "METHOD_NOT_ALLOWED", message: "Only GET and HEAD are supported" } });
      return;
    }

    if (requestUrl.pathname === "/" || requestUrl.pathname === "/index.html") {
      void sendDashboardHtml(response, templatePath, { refreshMs }, request.method === "HEAD")
        .catch((error: unknown) => {
          const message = error instanceof Error ? error.message : String(error);
          sendJson(response, 500, { error: { code: "DASHBOARD_TEMPLATE_READ_FAILED", message } });
        });
      return;
    }

    if (requestUrl.pathname === "/graph" || requestUrl.pathname === "/graph.html") {
      void summarizeBrainUsage({ ...workspaceOptions, scope: "all" })
        .then(async (metrics) => {
          if (metrics.kind === "missing") {
            sendGraphStatusHtml(response, 200, "Brain Usage Graph", metrics.message, request.method === "HEAD");
            return;
          }
          if (metrics.kind === "malformed") {
            sendGraphStatusHtml(response, 500, "Brain Usage Graph", metrics.message, request.method === "HEAD");
            return;
          }
          const html = request.method === "HEAD" ? "" : await renderLensGraphHtml(metrics, workspaceOptions);
          sendResponse(response, 200, html, "text/html; charset=utf-8");
        })
        .catch((error: unknown) => {
          const message = error instanceof Error ? error.message : String(error);
          sendGraphStatusHtml(response, 502, "Brain Usage Graph Unavailable", message, request.method === "HEAD");
        });
      return;
    }

    if (requestUrl.pathname === "/api/metrics") {
      void summarizeBrainUsage({ ...workspaceOptions, scope: "all" })
        .then((metrics) => {
          sendJson(response, 200, request.method === "HEAD" ? {} : metrics);
        })
        .catch((error: unknown) => {
          const message = error instanceof Error ? error.message : String(error);
          sendJson(response, 500, { error: { code: "METRICS_READ_FAILED", message } });
        });
      return;
    }

    sendJson(response, 404, { error: { code: "NOT_FOUND", message: "Route not found" } });
  });

  const listen = new Promise<void>((resolveListen, rejectListen) => {
    server.once("error", rejectListen);
    server.listen(port, host, () => {
      server.off("error", rejectListen);
      resolveListen();
    });
  });
  await listen;

  const address = server.address();
  if (address === null || typeof address === "string") throw new Error("Dashboard server did not expose a TCP address");
  const url = `http://${host}:${address.port}/`;

  if (flags.json) {
    process.stdout.write(
      `${JSON.stringify(
        {
          kind: "ok",
          url,
          graph_url: `${url}graph`,
          host,
          port: address.port,
          refresh_ms: refreshMs,
        },
        null,
        2,
      )}\n`,

);
    return;
  }

  process.stdout.write(
    [`Brain usage dashboard: ${url}`, `Trace graph: ${url}graph`, `Metrics endpoint: ${url}api/metrics`].join("\n") + "\n",
  );
}

async function skillsLog(args: string[]): Promise<void> {
  const flags = parseFlags(args);
  const result = await recordSkillInvocation({
    cwd: flags.cwd,
    stateRoot: flags["state-root"],
    invocation: {
      skill: requiredFlag(flags, "skill"),
      trigger: requiredFlag(flags, "trigger"),
      outcome: parseSkillInvocationOutcome(flags.outcome),
      reason: requiredFlag(flags, "reason"),
      host: requiredFlag(flags, "host"),
      session_id: requiredFlag(flags, "session-id"),
      ...(flags["turn-id"] !== undefined ? { turn_id: flags["turn-id"] } : {}),
      ...(flags["message-id"] !== undefined ? { message_id: flags["message-id"] } : {}),
    },
  });

  if (flags.json) {
    process.stdout.write(`${JSON.stringify(result, null, 2)}\n`);
    return;
  }
  process.stdout.write(`Recorded skill invocation ${result.record.id}: ${result.record.skill} (${result.record.outcome})\n`);
}

async function skillsInvocations(args: string[]): Promise<void> {
  const flags = parseFlags(args);
  const result = await readSkillInvocations({
    cwd: flags.cwd,
    stateRoot: flags["state-root"],
    limit: parseLimit(flags.limit),
    offset: parseNonNegativeIntegerFlag(flags.offset, "offset"),
    skill: flags.skill,
    ...(flags.outcome !== undefined ? { outcome: parseSkillInvocationOutcome(flags.outcome) } : {}),
    ...(flags["session-id"] !== undefined ? { session_id: flags["session-id"] } : {}),
  });

  if (flags.json) {
    process.stdout.write(`${JSON.stringify(result, null, 2)}\n`);
    return;
  }

  if (result.kind === "missing") {
    process.stdout.write(`No skill invocation journal found at ${result.path}\n`);
    return;
  }
  if (result.kind === "malformed") {
    process.stdout.write(`Malformed skill invocation journal at ${result.path}: ${result.message}\n`);
    return;
  }
  for (const item of result.items) {
    const reason = item.reason ? ` - ${item.reason}` : "";
    process.stdout.write(`${item.created_at} ${item.skill} ${item.outcome}: ${item.trigger}${reason}\n`);
  }
  process.stdout.write(
    `Showing ${result.pagination.returned} of ${result.summary.matching} matching records; next offset ${result.pagination.next_offset ?? "none"}.\n`,
  );
}

async function skillsAuditSample(args: string[]): Promise<void> {
  const flags = parseFlags(args);
  const result = await sampleSkillInvocations({
    cwd: flags.cwd,
    stateRoot: flags["state-root"],
    seed: requiredFlag(flags, "seed"),
    size: parseNonNegativeIntegerFlag(flags.size, "size"),
    skill: flags.skill,
    ...(flags.outcome !== undefined ? { outcome: parseSkillInvocationOutcome(flags.outcome) } : {}),
    ...(flags["session-id"] !== undefined ? { session_id: flags["session-id"] } : {}),
  });

  if (flags.json) {
    process.stdout.write(`${JSON.stringify(result, null, 2)}\n`);
    return;
  }
  if (result.kind === "missing") {
    process.stdout.write(`No skill invocation journal found at ${result.path}\n`);
    return;
  }
  if (result.kind === "malformed") {
    process.stdout.write(`Malformed skill invocation journal at ${result.path}: ${result.message}\n`);
    return;
  }
  process.stdout.write(
    `Audit sample ${result.seed}: ${result.items.length} of ${result.eligible} traceable matching records (${result.excluded_untraceable} legacy/untraceable excluded).\n`,
  );
  for (const item of result.items) {
    process.stdout.write(
      `${item.id} ${item.session_id}${item.turn_id ? `/${item.turn_id}` : ""} ${item.skill} ${item.outcome}: ${item.reason}\n`,
    );
  }
}

async function main(): Promise<void> {
  if (command.length === 0 || command[0] === "--help" || command[0] === "help") {
    process.stdout.write(`${usage()}\n`);
    return;
  }

  if (command[0] === "manifest") {
    const { runManifestCli } = await import("./manifest.ts");
    await runManifestCli(command.slice(1));
    return;
  }

  if (
    command[0] === "codex" &&
    (command[1] === "context-hook" || command[1] === "session-start-hook")
  ) {
    await runContextHook();
    return;
  }

  if (command[0] === "continuity" && command[1] === "read") {
    await continuityRead(command.slice(2));
    return;
  }

  if (command[0] === "work-context" && command[1] === "read") {
    await workContextRead(command.slice(2));
    return;
  }

  if (command[0] === "work-context" && command[1] === "doctor") {
    await workContextDoctor(command.slice(2));
    return;
  }

  if (command[0] === "continuity" && command[1] === "doctor") {
    await continuityDoctor(command.slice(2));
    return;
  }

  if (command[0] === "continuity" && command[1] === "routing-audit") {
    await continuityRoutingAudit(command.slice(2));
    return;
  }

  if (command[0] === "continuity" && command[1] === "init-default") {
    await continuityInitDefault(command.slice(2));
    return;
  }

  if (command[0] === "brain" && command[1] === "log") {
    await brainLog(command.slice(2));
    return;
  }

  if (command[0] === "brain" && command[1] === "usage") {
    await brainUsage(command.slice(2));
    return;
  }

  if (command[0] === "brain" && command[1] === "metrics") {
    await brainMetrics(command.slice(2));
    return;
  }

  if (command[0] === "brain" && command[1] === "dashboard") {
    await brainDashboard(command.slice(2));
    return;
  }

  if (command[0] === "skills" && command[1] === "log") {
    await skillsLog(command.slice(2));
    return;
  }

  if (command[0] === "skills" && command[1] === "invocations") {
    await skillsInvocations(command.slice(2));
    return;
  }

  if (command[0] === "skills" && command[1] === "audit-sample") {
    await skillsAuditSample(command.slice(2));
    return;
  }

  if (command[0] === "tool-result" && command[1] === "capture") {
    await captureToolResult(command.slice(2));
    return;
  }

  if (command[0] === "browser") {
    const exitCode = await runBrowserCli(command.slice(1), {
      anvilCommand: currentFile,
      ...(process.env.ANVIL_HOME ? { anvilHome: process.env.ANVIL_HOME } : {}),
    });
    if (exitCode !== 0) process.exitCode = exitCode;
    return;
  }

  if (command[0] === "mcp" && command[1] === "serve") {
    await runAnvilMcpServer();
    return;
  }

  fail(usage());
}

if (process.argv[1] && realpathSync(resolve(process.argv[1])) === currentFile) {
  main().catch((error) => {
    const message = error instanceof ToolResultError
      ? `${error.code}: ${error.message}`
      : error instanceof Error
        ? error.message
        : String(error);
    fail(message);
  });
}
